css:
.cb-stage { position: relative; border: 2px solid var(--ink); border-radius: 12px; overflow: hidden; }
.cb-stage canvas { touch-action: none; cursor: grab; }
.cb-stage canvas.holding { cursor: grabbing; }
.cb-paths { display: flex; flex-wrap: wrap; gap: 6px; margin: 0; padding: 0; list-style: none; }
.cb-paths li { font-size: 16px; padding: 3px 10px; border-radius: 999px; border: 2px dashed #b7bfca; color: #8a93a2; }
.cb-paths li.on { border: 2px solid var(--accent); background: #fff3c2; color: var(--ink); font-weight: 800; }
.cb-meter { display: grid; gap: 4px; }
.cb-meter p { display: grid; grid-template-columns: 5.4em 1fr 3em; align-items: center; gap: 8px; margin: 0; font-size: 18px; }
.cb-meter em { display: block; height: 14px; background: #e6e9ee; border-radius: 7px; overflow: hidden; }
.cb-meter i { display: block; height: 100%; width: 0; border-radius: 7px; transition: width .3s; }
.cb-co2 i { background: #8a7a6a; } .cb-ph i { background: #3f8fd8; }
.cb-meter b { text-align: right; font-variant-numeric: tabular-nums; }
.cb-out { margin: 0; font-size: 20px; line-height: 1.5; background: #fffbe6; border: 2px solid var(--accent); border-radius: 12px; padding: 8px 14px; min-height: 4.6em; }

